export function rentalQuote(startDate, endDate, pricePerDay, today) {
  if (!startDate || !endDate) {
    return { days: 0, total: 0, error: null };
  }

  const parseDate = (dateStr) => new Date(dateStr.split('-'));

  const start = parseDate(startDate);
  const end = parseDate(endDate);
  const now = parseDate(today);

  if (start < now) {
    return { days: 0, total: 0, error: 'Start date cannot be in the past.' };
  } else if (end < start) {
    return { days: 0, total: 0, error: 'End date must be after start date.' };
  }

  const timeDiff = end - start;
  const days = Math.ceil(timeDiff / (1000 * 60 * 60 * 24)) + 1;
  const total = days * pricePerDay;

  return { days, total, error: null };
}
